import{_ as r,o as e,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-05-29 :: Ceph Testing meeting","description":"","frontmatter":{"title":"2019-05-29 :: Ceph Testing meeting","date":"2019-05-29T00:00:00.000Z","updated":"2019-05-30T00:00:00.000Z","tags":["Ceph测试","分布式存储","Orchestrator","部署工具","KVM"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-05-29_-_-_Ceph_Testing_meeting.md","filePath":"posts/2019/2019-05-29_-_-_Ceph_Testing_meeting.md","lastUpdated":1780459816000}'),s={name:"posts/2019/2019-05-29_-_-_Ceph_Testing_meeting.md"};function l(a,t,n,p,g,_){return e(),i("div",null,[...t[0]||(t[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年5月29日</p><p><strong>参会人员</strong>： Vacuum, Pakrac, Gretchen, Yuri, Yuki, Danka, DTRS, Zach, others</p><p><strong>会议主题</strong>： Ceph分布式存储的测试与部署工具讨论</p><p><strong>关键细节</strong>：</p><ul><li><strong>Orchestrator测试</strong>： Vacuum表示将参与每周会议，直到Orchestrator测试完善。目前对Orchestrator的最终进展并不自信。</li><li><strong>Barcelona会议</strong>： Pakrac分享了参加Barcelona会议的经验，认为会议内容丰富，但在测试方面遇到了一些挑战。</li><li><strong>降级与回滚</strong>： 讨论了降级与回滚的区别，并决定在每次点发布前进行测试，以确保新旧版本的数据兼容性。</li><li><strong>部署工具</strong>： 讨论了Ceph的部署工具，包括Leap和Terraform。Yuki提到Leap目前仅适用于OpenStack，但可以考虑扩展到其他平台。</li><li><strong>KVM测试</strong>： 讨论了使用KVM进行测试的可能性，以及如何将部署工具与Terraform集成。</li></ul><p><strong>主要议题</strong>：</p><ul><li><strong>Orchestrator测试完善</strong>： 确保Orchestrator的稳定性和可靠性。</li><li><strong>降级与回滚测试</strong>： 确保每次点发布前进行测试，确保新旧版本的数据兼容性。</li><li><strong>部署工具优化</strong>： 优化Ceph的部署工具，使其更易于使用和扩展。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>Vacuum将定期参与会议，直到Orchestrator测试完善。</li><li>在每次点发布前进行测试，确保新旧版本的数据兼容性。</li><li>探索使用KVM进行测试的可能性，以及将部署工具与Terraform集成。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Vacuum将完善Orchestrator的测试。</li><li>团队成员将进行降级与回滚测试。</li><li>探索使用KVM进行测试的可能性，以及将部署工具与Terraform集成。</li></ul><p><strong>关键词</strong>：</p><ul><li>Orchestrator</li><li>测试</li><li>降级</li><li>回滚</li><li>部署工具</li><li>KVM</li><li>Terraform</li><li>Leap</li><li>OpenStack</li></ul>',14)])])}const h=r(s,[["render",l]]);export{u as __pageData,h as default};
